/**
 * The ahead-of-time Layer 1 validators (dist/schema-validators.js,
 * generated by scripts/compile-validators.mjs): they must be current
 * for the bundled schemas, load as a plain ES module with no runtime
 * code generation, and judge exactly as Ajv compiling the same schemas
 * at load time would.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv2020Module from "ajv/dist/2020.js";
import addFormatsModule from "ajv-formats";
import { SCHEMAS } from "../dist/generated/schemas.js";
import { VALIDATORS } from "../dist/schema-validators.js";
import { schemaDigest, BUNDLED_SCHEMAS } from "../scripts/compile-validators.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const generated = readFileSync(join(here, "..", "dist", "schema-validators.js"), "utf8");

test("generated validators match the bundled schemas (drift test)", () => {
  const recorded = /schemas sha256 ([0-9a-f]{64})/.exec(generated)?.[1];
  assert.equal(
    recorded,
    schemaDigest(...BUNDLED_SCHEMAS),
    "schema-validators.js has drifted from the bundled schemas — run npm run build"
  );
});

test("generated validators are a plain ES module: no require, no code generation", () => {
  assert.ok(!/require\(/.test(generated), "generated code still calls require");
  assert.ok(!/new Function\(|\beval\(/.test(generated), "generated code generates code");
  const imports = [...generated.matchAll(/^import .* from "([^"]+)";$/gm)].map((m) => m[1]);
  assert.deepEqual(imports, ["ajv/dist/runtime/ucs2length.js", "ajv-formats/dist/formats.js"]);
});

test("generated validators agree with Ajv compiled at load time, on every fixture", () => {
  const Ajv2020 = Ajv2020Module.default;
  const addFormats = addFormatsModule.default;
  const ajv = new Ajv2020({ allErrors: true, allowUnionTypes: true });
  addFormats(ajv);
  const reference = Object.fromEntries(
    Object.entries(SCHEMAS).map(([id, schema]) => [id, ajv.compile(schema)])
  );
  const generatedFns = VALIDATORS;
  assert.deepEqual(Object.keys(generatedFns).sort(), Object.keys(reference).sort());

  const files = [];
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (name.endsWith(".json") && !name.endsWith(".expected.json")) files.push(p);
    }
  };
  walk(join(here, "fixtures"));
  walk(join(here, "cli-fixtures"));
  walk(join(here, "..", "..", "case-studies"));
  assert.ok(files.length > 50, `expected the fixture corpus, found ${files.length} files`);

  for (const file of files) {
    const doc = JSON.parse(readFileSync(file, "utf8"));
    for (const kind of Object.keys(reference)) {
      const expected = reference[kind](doc);
      const actual = generatedFns[kind](doc);
      assert.equal(actual, expected, `${kind} verdict differs on ${file}`);
      const norm = (errors) =>
        (errors ?? []).map((e) => [e.instancePath, e.keyword, e.message]).sort();
      assert.deepEqual(norm(generatedFns[kind].errors), norm(reference[kind].errors), `${kind} errors differ on ${file}`);
    }
  }
});
